#include <iostream>
#include <numeric>
#include <stdexcept>

class RationalNumber {
private:
    int numerator;
    int denominator;

    void reduce() {
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        int g = std::gcd(numerator, denominator);
        if (g != 0) {
            numerator /= g;
            denominator /= g;
        }
    }

public:
    RationalNumber(int num = 0, int denom = 1) : numerator(num), denominator(denom) {
        if (denominator == 0) {
            throw std::invalid_argument("Denominator cannot be zero.");
        }
        reduce();
    }

    RationalNumber operator+(const RationalNumber& rhs) const {
        return RationalNumber(numerator * rhs.denominator + rhs.numerator * denominator,
                              denominator * rhs.denominator);
    }

    RationalNumber operator-(const RationalNumber& rhs) const {
        return RationalNumber(numerator * rhs.denominator - rhs.numerator * denominator,
                              denominator * rhs.denominator);
    }

    bool operator==(const RationalNumber& rhs) const {
        return numerator == rhs.numerator && denominator == rhs.denominator;
    }

    bool operator<(const RationalNumber& rhs) const {
        return numerator * rhs.denominator < rhs.numerator * denominator;
    }

    friend std::ostream& operator<<(std::ostream& os, const RationalNumber& r) {
        if (r.denominator == 1) {
            os << r.numerator;
        } else {
            os << r.numerator << "/" << r.denominator;
        }
        return os;
    }
};

int main() {
    RationalNumber r1(7, 3);
    RationalNumber r2(1, -6); // Normalized to -1/6
    RationalNumber sum = r1 + r2;
    RationalNumber diff = r1 - r2;

    std::cout << "r1: " << r1 << "\n";
    std::cout << "r2: " << r2 << "\n";
    std::cout << "r1 + r2 = " << sum << "\n";
    std::cout << "r1 - r2 = " << diff << "\n";
    std::cout << "r1 == r2: " << (r1 == r2 ? "true" : "false") << "\n";
    std::cout << "r2 < r1: " << (r2 < r1 ? "true" : "false") << "\n";

    return 0;
}
